[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --blue:#3861FB;--navy:#0D1421;--gray:#808A9D;--green:#16c784;--red:#ea3943;
  --bg:#fff;--bg2:#f8f9fa;--bg3:#f0f2f5;--border:#e8eaed;--text:#0D1421;--text2:#58667e;
  --radius:8px;--font:'Inter',system-ui,sans-serif;--mono:'JetBrains Mono','Inter',monospace;
}
html{font-size:14px;scroll-behavior:smooth}
body{font-family:var(--font);color:var(--text);background:var(--bg);line-height:1.5;-webkit-font-smoothing:antialiased}
a{color:var(--blue);text-decoration:none}
a:hover{text-decoration:underline}
button{font-family:var(--font);cursor:pointer}
.tabnum{font-family:var(--mono);font-feature-settings:'tnum';letter-spacing:-0.02em}

/* Top Stats Bar */
.stats-bar{background:var(--bg2);border-bottom:1px solid var(--border);padding:8px 0;font-size:.8rem}
.stats-bar .container{display:flex;align-items:center;gap:24px;flex-wrap:wrap}
.stat-item{display:flex;align-items:center;gap:6px;white-space:nowrap}
.stat-label{color:var(--text2);font-weight:500}
.stat-value{font-weight:600;font-family:var(--mono)}
.stat-change{font-weight:600;font-size:.75rem}
.stat-change.pos{color:var(--green)}
.stat-change.neg{color:var(--red)}
.stat-badge{display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:4px;font-size:.75rem;font-weight:600}
.badge-neutral{background:#fff3cd;color:#856404}
.badge-season{background:#e8f0fe;color:#1a56db}

/* Navigation */
.main-nav{background:var(--bg);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:100}
.nav-inner{display:flex;align-items:center;height:56px;gap:8px}
.nav-logo{display:flex;align-items:center;gap:8px;font-weight:700;font-size:1.15rem;color:var(--navy);margin-right:16px;white-space:nowrap}
.nav-logo svg{flex-shrink:0}
.nav-links{display:flex;align-items:center;gap:2px;flex:1;overflow-x:auto}
.nav-link{padding:6px 12px;border-radius:6px;font-size:.85rem;font-weight:500;color:var(--text2);transition:all .15s;white-space:nowrap;border:none;background:none}
.nav-link:hover{background:var(--bg2);color:var(--text)}
.nav-link.active{color:var(--blue);background:#eef1ff}
.nav-right{display:flex;align-items:center;gap:8px;margin-left:auto}
.btn-login{padding:6px 16px;border-radius:6px;font-size:.85rem;font-weight:500;color:var(--blue);border:1px solid var(--blue);background:none;transition:all .15s}
.btn-login:hover{background:var(--blue);color:#fff}
.btn-signup{padding:6px 16px;border-radius:6px;font-size:.85rem;font-weight:600;color:#fff;background:var(--blue);border:none;transition:all .15s}
.btn-signup:hover{background:#2b4fe6}
.container{max-width:1320px;margin:0 auto;padding:0 20px}

/* Promo Banner */
.promo-banner{background:linear-gradient(135deg,#1a1f3c 0%,#2d1b69 50%,#1a3a5c 100%);padding:14px 0;position:relative;overflow:hidden}
.promo-track{display:flex;transition:transform .4s ease}
.promo-slide{min-width:100%;display:flex;align-items:center;justify-content:center;gap:12px;color:#fff;font-size:.9rem;font-weight:500;padding:0 20px}
.promo-slide strong{color:#a5b4fc}
.promo-cta{padding:4px 14px;border-radius:4px;background:rgba(255,255,255,.15);color:#fff;font-size:.8rem;font-weight:600;border:1px solid rgba(255,255,255,.2);transition:all .15s}
.promo-cta:hover{background:rgba(255,255,255,.25);text-decoration:none}
.promo-dots{display:flex;gap:6px;justify-content:center;margin-top:8px}
.promo-dot{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.3);border:none;cursor:pointer;padding:0;transition:all .2s}
.promo-dot.active{background:#fff;width:18px;border-radius:3px}

/* AI Alerts */
.ai-bar{background:var(--bg2);border-bottom:1px solid var(--border);padding:10px 0}
.ai-inner{display:flex;align-items:center;gap:12px;overflow-x:auto}
.ai-label{display:flex;align-items:center;gap:6px;font-weight:600;font-size:.85rem;white-space:nowrap;color:var(--blue)}
.ai-prompt{flex:1;min-width:200px;padding:6px 12px;border:1px solid var(--border);border-radius:6px;font-size:.8rem;color:var(--text2);background:var(--bg);cursor:pointer;transition:all .15s}
.ai-prompt:hover{border-color:var(--blue);color:var(--text)}
.ai-tags{display:flex;gap:6px;overflow-x:auto;padding:2px 0}
.ai-tag{padding:4px 10px;border-radius:20px;font-size:.75rem;font-weight:500;color:var(--text2);background:var(--bg);border:1px solid var(--border);white-space:nowrap;cursor:pointer;transition:all .15s}
.ai-tag:hover{border-color:var(--blue);color:var(--blue);background:#eef1ff}

/* Tabs */
.tabs-row{display:flex;align-items:center;border-bottom:2px solid var(--border);gap:0;overflow-x:auto}
.tab-btn{padding:10px 16px;font-size:.85rem;font-weight:500;color:var(--text2);border:none;background:none;border-bottom:2px solid transparent;margin-bottom:-2px;cursor:pointer;transition:all .15s;white-space:nowrap}
.tab-btn:hover{color:var(--text)}
.tab-btn.active{color:var(--blue);border-bottom-color:var(--blue);font-weight:600}
.network-tabs{background:var(--bg2);border-bottom:1px solid var(--border);padding:8px 0}
.network-tabs .tabs-row{border-bottom:none}
.ntab-btn{padding:5px 14px;border-radius:20px;font-size:.8rem;font-weight:500;color:var(--text2);border:1px solid var(--border);background:var(--bg);cursor:pointer;transition:all .15s;white-space:nowrap}
.ntab-btn:hover{border-color:var(--blue);color:var(--blue)}
.ntab-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}

/* Table Controls */
.table-controls{display:flex;align-items:center;gap:8px;padding:12px 0;flex-wrap:wrap}
.tc-btn{padding:5px 12px;border-radius:6px;font-size:.8rem;font-weight:500;color:var(--text2);background:var(--bg);border:1px solid var(--border);cursor:pointer;transition:all .15s;display:inline-flex;align-items:center;gap:4px}
.tc-btn:hover{border-color:var(--blue);color:var(--blue)}
.tc-btn.active-sort{background:#eef1ff;color:var(--blue);border-color:var(--blue)}
.tc-right{margin-left:auto;display:flex;gap:8px}

/* Table */
.crypto-table-wrap{overflow-x:auto;border:1px solid var(--border);border-radius:var(--radius);margin-bottom:4px}
.crypto-table{width:100%;border-collapse:collapse;font-size:.82rem}
.crypto-table thead{background:var(--bg2);position:sticky;top:56px;z-index:10}
.crypto-table th{padding:10px 12px;font-weight:600;font-size:.78rem;color:var(--text2);text-transform:uppercase;letter-spacing:.03em;white-space:nowrap;border-bottom:1px solid var(--border);text-align:left;cursor:pointer;user-select:none;transition:color .15s}
.crypto-table th:hover{color:var(--text)}
.crypto-table th.right,#rankCol,#priceCol,#pctCols,#mcapCol,#volCol,#supplyCol,#chartCol{text-align:right}
.crypto-table th.right{text-align:right}
.crypto-table th.center{text-align:center}
.crypto-table td{padding:10px 12px;border-bottom:1px solid var(--border);vertical-align:middle}
.crypto-table tbody tr{transition:background .1s}
.crypto-table tbody tr:hover{background:var(--bg2)}
.rank-cell{color:var(--text2);font-family:var(--mono);font-size:.78rem;width:40px;text-align:center}
.name-cell{display:flex;align-items:center;gap:8px;min-width:160px}
.coin-icon{width:24px;height:24px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:.65rem;color:#fff}
.coin-name{font-weight:600;color:var(--text)}
.coin-symbol{color:var(--text2);font-size:.78rem;margin-left:2px}
.price-cell{font-family:var(--mono);font-weight:500;text-align:right}
.pct-cell{font-family:var(--mono);font-weight:500;text-align:right;font-size:.8rem}
.pct-pos{color:var(--green)}
.pct-neg{color:var(--red)}
.mcap-cell,.vol-cell,.supply-cell{font-family:var(--mono);text-align:right;color:var(--text);font-weight:500}
.supply-sym{color:var(--text2);font-size:.72rem;margin-left:2px}
.sparkline-cell{text-align:right;width:120px}
.sparkline-cell svg{display:block;margin-left:auto}

/* Pagination */
.pagination{display:flex;align-items:center;justify-content:space-between;padding:14px 0;border-top:1px solid var(--border);flex-wrap:wrap;gap:8px}
.page-info{font-size:.82rem;color:var(--text2)}
.page-btns{display:flex;gap:4px}
.page-btn{width:34px;height:34px;display:flex;align-items:center;justify-content:center;border-radius:6px;font-size:.82rem;font-weight:500;color:var(--text2);background:var(--bg);border:1px solid var(--border);cursor:pointer;transition:all .15s}
.page-btn:hover{border-color:var(--blue);color:var(--blue)}
.page-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}

/* Index Row */
.index-row{background:#f0f4ff;border-bottom:1px solid #d0daf0}
.index-row td{padding:8px 12px;font-size:.82rem}
.index-label{font-weight:600;color:var(--blue)}
.index-ticker{color:var(--text2);font-size:.72rem;margin-left:4px}

/* Market Summary */
.market-summary{padding:32px 0;border-top:1px solid var(--border)}
.market-summary h2{font-size:1.15rem;font-weight:700;margin-bottom:12px}
.market-summary p{color:var(--text2);line-height:1.7;font-size:.9rem}
.market-summary strong{color:var(--text)}
.read-more-btn{color:var(--blue);font-weight:600;font-size:.85rem;cursor:pointer;background:none;border:none;padding:4px 0;margin-top:4px}
.read-more-btn:hover{text-decoration:underline}
.summary-extra{display:none;margin-top:8px;color:var(--text2);line-height:1.7;font-size:.9rem}
.summary-extra.open{display:block}

/* Info Content */
.info-content{padding:32px 0;border-top:1px solid var(--border)}
.info-content h2{font-size:1.1rem;font-weight:700;margin-bottom:8px}
.info-content h3{font-size:.95rem;font-weight:600;margin:16px 0 6px}
.info-content p{color:var(--text2);line-height:1.7;font-size:.88rem}

/* Footer */
.main-footer{background:var(--bg2);border-top:1px solid var(--border);padding:40px 0 24px;margin-top:40px}
.footer-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:32px;margin-bottom:32px}
.footer-col h4{font-size:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text);margin-bottom:12px}
.footer-col a{display:block;font-size:.82rem;color:var(--text2);padding:3px 0;transition:color .15s}
.footer-col a:hover{color:var(--blue);text-decoration:none}
.footer-bottom{border-top:1px solid var(--border);padding-top:16px;display:flex;justify-content:space-between;align-items:center;font-size:.78rem;color:var(--text2);flex-wrap:wrap;gap:8px}
.footer-social{display:flex;gap:12px}
.footer-social a{color:var(--text2);transition:color .15s}
.footer-social a:hover{color:var(--blue);text-decoration:none}

/* Dropdowns */
.dropdown-panel{position:absolute;top:100%;left:0;background:var(--bg);border:1px solid var(--border);border-radius:var(--radius);box-shadow:0 8px 24px rgba(0,0,0,.1);padding:12px;z-index:50;min-width:200px;display:none}
.dropdown-panel.open{display:block}
.dropdown-panel label{display:flex;align-items:center;gap:8px;padding:6px 0;font-size:.82rem;cursor:pointer;color:var(--text)}
.dropdown-panel input[type=checkbox]{accent-color:var(--blue)}

/* Filter Panel */
.filter-panel{background:var(--bg2);border:1px solid var(--border);border-radius:var(--radius);padding:16px;margin-bottom:12px;display:none}
.filter-panel.open{display:block}
.filter-row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}
.filter-group{display:flex;flex-direction:column;gap:4px}
.filter-group label{font-size:.75rem;font-weight:600;color:var(--text2);text-transform:uppercase}
.filter-group input,.filter-group select{padding:6px 10px;border:1px solid var(--border);border-radius:6px;font-size:.82rem;font-family:var(--font)}

/* Responsive */
@media(max-width:768px){
  .stats-bar .container{gap:12px;font-size:.75rem}
  .nav-links{display:none}
  .ai-tags{display:none}
  .footer-grid{grid-template-columns:repeat(2,1fr)}
  .crypto-table{font-size:.78rem}
  .coin-icon{width:20px;height:20px;font-size:.55rem}
}
@media(max-width:480px){
  .footer-grid{grid-template-columns:1fr}
}

/* Scrollbar */
::-webkit-scrollbar{height:6px;width:6px}
::-webkit-scrollbar-track{background:var(--bg2)}
::-webkit-scrollbar-thumb{background:var(--border);border-radius:3px}
::-webkit-scrollbar-thumb:hover{background:var(--gray)}

/* Animations */
@keyframes fadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
.fade-in{animation:fadeIn .3s ease-out}
</style>
</head>
<body>

