// ============ SPARKLINE GENERATOR ============
function genSparkline(pctW, pctD) {
  const pts = [];
  const w = 100, h = 32, n = 14;
  let y = h / 2;
  for (let i = 0; i < n; i++) {
    const drift = (pctW > 0 ? -1 : 1) * (Math.random() * 2 + 0.3);
    const noise = (Math.random() - 0.5) * 4;
    y = Math.max(2, Math.min(h - 2, y + drift + noise));
    pts.push(`${(i / (n - 1)) * w},${y.toFixed(1)}`);
  }
  const color = pctD >= 0 ? 'var(--green)' : 'var(--red)';
  return `<svg width="100" height="32" viewBox="0 0 100 32"><polyline points="${pts.join(' ')}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
}

// ============ FORMATTING ============
function fmtPrice(p) {
  if (p >= 1000) return '$' + p.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
  if (p >= 1) return '$' + p.toLocaleString('en-US', {minimumFractionDigits:2, maximumFractionDigits:2});
  if (p >= 0.01) return '$' + p.toFixed(4);
  return '$' + p.toFixed(8);
}
function fmtMcap(v) {
  if (v >= 1e12) return '$' + (v/1e12).toFixed(2) + 'T';
  if (v >= 1e9) return '$' + (v/1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v/1e6).toFixed(2) + 'M';
  return '$' + v.toLocaleString();
}
function fmtVol(v) {
  if (v >= 1e9) return '$' + (v/1e9).toFixed(2) + 'B';
  if (v >= 1e6) return '$' + (v/1e6).toFixed(2) + 'M';
  return '$' + v.toLocaleString();
}
function fmtSupply(v, sym) {
  if (v >= 1e12) return (v/1e12).toFixed(2) + 'T ' + sym;
  if (v >= 1e9) return (v/1e9).toFixed(2) + 'B ' + sym;
  if (v >= 1e6) return (v/1e6).toFixed(2) + 'M ' + sym;
  return v.toLocaleString() + ' ' + sym;
}
function fmtPct(v) {
  const sign = v >= 0 ? '+' : '';
  return sign + v.toFixed(2) + '%';
}
function pctClass(v) { return v >= 0 ? 'pct-pos' : 'pct-neg'; }

// ============ RENDER TABLE ============
let currentSort = 'mcap';
let sortDir = -1; // -1 = desc

function renderTable(coins) {
  const body = document.getElementById('cryptoBody');
  let html = '';

  // Index row
  html += `<tr class="index-row">
    <td class="rank-cell" style="text-align:center">★</td>
    <td><span class="index-label">CoinTracker 20 Index<span class="index-ticker">DTFCTP20</span></span></td>
    <td class="price-cell tabnum">$154.29</td>
    <td class="pct-cell tabnum pct-pos">+0.21%</td>
    <td class="pct-cell tabnum pct-pos">+1.15%</td>
    <td class="pct-cell tabnum pct-pos">+4.97%</td>
    <td class="mcap-cell tabnum">—</td>
    <td class="vol-cell tabnum">—</td>
    <td class="supply-cell tabnum">—</td>
    <td class="sparkline-cell">${genSparkline(4.97, 1.15)}</td>
  </tr>`;

  coins.forEach(c => {
    html += `<tr>
      <td class="rank-cell">${c.r}</td>
      <td><div class="name-cell"><div class="coin-icon" style="background:${c.color}">${c.sym.charAt(0)}</div><span class="coin-name">${c.name}</span><span class="coin-symbol">${c.sym}</span></div></td>
      <td class="price-cell tabnum">${fmtPrice(c.price)}</td>
      <td class="pct-cell tabnum ${pctClass(c.h)}">${fmtPct(c.h)}</td>
      <td class="pct-cell tabnum ${pctClass(c.d)}">${fmtPct(c.d)}</td>
      <td class="pct-cell tabnum ${pctClass(c.w)}">${fmtPct(c.w)}</td>
      <td class="mcap-cell tabnum">${fmtMcap(c.mcap)}</td>
      <td class="vol-cell tabnum">${fmtVol(c.vol)}</td>
      <td class="supply-cell tabnum">${fmtSupply(c.sup, c.supSym)}</td>
      <td class="sparkline-cell">${genSparkline(c.w, c.d)}</td>
    </tr>`;
  });
  body.innerHTML = html;
}

function sortCoins(coins, key) {
  return [...coins].sort((a, b) => {
    const vals = {mcap: 'mcap', vol: 'vol'};
    const k = vals[key] || 'mcap';
    return sortDir * (a[k] - b[k]);
  });
}

