  if (cat === 'trending') {
    displayedCoins = [...COINS].sort(() => Math.random() - 0.5).slice(0, 100);
  } else if (cat === 'watchlist') {
    displayedCoins = COINS.slice(0, 15);
  } else if (cat === 'new') {
    displayedCoins = [...COINS].sort((a, b) => b.r - a.r).slice(0, 20);
  } else {
    displayedCoins = [...COINS];
  }
  renderTable(displayedCoins);
});

